/* ================= Base ================= */
:root {
  --ink: #03101a;
  --ink-2: #061c29;
  --glass: rgba(5, 22, 33, 0.5);
  --glass-strong: rgba(4, 17, 26, 0.78);
  --line: rgba(226, 240, 244, 0.13);
  --line-gold: rgba(233, 200, 138, 0.35);
  --gold: #e9c88a;
  --gold-bright: #ffe4ac;
  --aqua: #8fe3d6;
  --text: #eaf4f7;
  --muted: rgba(214, 232, 238, 0.62);
  --serif: "Amiri", "FreeSerif", "DejaVu Serif", serif;
  --sans: "Cairo", "Lato", "DejaVu Sans", sans-serif;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #03101a;
  color: var(--text);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { touch-action: none; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: radial-gradient(120% 100% at 50% 100%, #0b3145 0%, #051a27 45%, #020b12 100%);
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

.grade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(2, 10, 16, 0.32) 0%, rgba(2, 10, 16, 0) 18%, rgba(2, 10, 16, 0) 72%, rgba(2, 8, 13, 0.55) 100%);
  mix-blend-mode: multiply;
  opacity: 0.8;
}
.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 46%, transparent 48%, rgba(2, 9, 14, 0.34) 82%, rgba(1, 6, 10, 0.62) 100%);
}
.grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3'/%3E%3C/filter%3E%3Crect width='180' height='180' filter='url(%23n)' opacity='0.8'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}

/* ================= HUD shell ================= */
.hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 1;
  transition: opacity 1s var(--ease);
  font-family: var(--sans);
  direction: rtl;
  padding: max(18px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
  z-index: 20;
}
.hud.is-hidden { opacity: 0; pointer-events: none; }

.glass {
  background: linear-gradient(160deg, rgba(9, 32, 46, 0.62), rgba(3, 14, 22, 0.58));
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.26), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(14px) saturate(1.15);
  -webkit-backdrop-filter: blur(14px) saturate(1.15);
}

.hud-top {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 20px;
  position: relative;
  z-index: 3;
}

/* ---- brand / stats ---- */
.brand-block { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }
.brand { display: flex; align-items: center; gap: 11px; }
.brand-mark {
  width: 42px; height: 42px;
  display: grid; place-items: center;
  color: var(--gold-bright);
  border: 1px solid var(--line-gold);
  border-radius: 50%;
  background: radial-gradient(circle at 32% 24%, rgba(255, 228, 172, 0.16), rgba(4, 18, 27, 0.5));
  box-shadow: 0 0 22px rgba(233, 200, 138, 0.13), inset 0 0 12px rgba(233, 200, 138, 0.08);
}
.brand-mark svg { width: 23px; height: 23px; }
.brand-text { display: flex; flex-direction: column; line-height: 1.05; }
.brand-text b { font-family: var(--serif); font-size: 25px; font-weight: 700; letter-spacing: 0.01em; color: #f8fbfc; text-shadow: 0 2px 18px rgba(0, 0, 0, 0.4); }
.brand-text small { font-size: 8.5px; letter-spacing: 0.34em; color: var(--gold); opacity: 0.8; margin-top: 4px; }

.chips { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  display: flex; align-items: baseline; gap: 5px;
  padding: 7px 11px 7px 9px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(4, 18, 27, 0.44);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  font-size: 12px;
  color: var(--muted);
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.18);
}
.chip b { font-size: 15px; color: #f4fafb; font-weight: 600; font-variant-numeric: tabular-nums; }
.chip-label { font-size: 10.5px; color: var(--muted); }
.chip-ico { width: 15px; height: 15px; display: inline-grid; place-items: center; color: var(--aqua); transform: translateY(2px); }
.chip-ico svg { width: 15px; height: 15px; }
.chip-ico.gold { color: var(--gold-bright); }

/* ---- compass ---- */
.compass-wrap {
  position: relative;
  width: min(44vw, 460px);
  height: 64px;
  margin-top: 2px;
  filter: drop-shadow(0 8px 22px rgba(0, 0, 0, 0.34));
}
#compass { width: 100%; height: 100%; display: block; }
.compass-needle {
  position: absolute; top: 2px; left: 50%;
  width: 0; height: 0;
  transform: translateX(-50%);
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  border-top: 9px solid var(--gold-bright);
  filter: drop-shadow(0 0 6px rgba(255, 210, 130, 0.7));
}

/* ---- map ---- */
.map-block { display: flex; flex-direction: column; align-items: flex-end; gap: 8px; position: relative; }
.minimap-shell {
  position: relative;
  width: 154px; height: 154px;
  border-radius: 50%;
  padding: 6px;
  background: radial-gradient(circle at 38% 30%, rgba(13, 44, 60, 0.7), rgba(3, 14, 22, 0.8));
  border: 1px solid var(--line-gold);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.34), inset 0 0 24px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
#minimap { width: 100%; height: 100%; border-radius: 50%; display: block; }
.minimap-ring { position: absolute; inset: 12px; border: 1px solid rgba(233, 200, 138, 0.12); border-radius: 50%; pointer-events: none; }
.minimap-north { position: absolute; top: -7px; left: 50%; transform: translateX(-50%); font-size: 9px; letter-spacing: 0.1em; color: var(--gold); background: rgba(4, 17, 26, 0.9); padding: 0 6px; border-radius: 4px; }
.conditions {
  display: flex; align-items: center; gap: 8px;
  font-size: 11px; color: var(--muted);
  letter-spacing: 0.04em;
  padding: 5px 11px;
  border-radius: 999px;
  background: rgba(4, 17, 26, 0.46);
  border: 1px solid var(--line);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.conditions .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--gold); opacity: 0.7; }
.icon-btn {
  position: absolute; left: -2px; top: 166px;
  width: 32px; height: 32px; border-radius: 50%;
  display: grid; place-items: center;
  color: var(--muted);
  background: rgba(4, 17, 26, 0.55);
  border: 1px solid var(--line);
  cursor: pointer; pointer-events: auto;
  transition: color 0.2s, border-color 0.2s, transform 0.2s;
  backdrop-filter: blur(8px);
}
.icon-btn:hover { color: var(--gold-bright); border-color: var(--line-gold); transform: scale(1.05); }
.icon-btn svg { width: 16px; height: 16px; }
.icon-btn .ico-off { display: none; }
.icon-btn.muted .ico-on { display: none; }
.icon-btn.muted .ico-off { display: block; }

/* ---- quest ---- */
.quest {
  position: absolute; top: 92px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px;
  padding: 7px 16px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(6, 23, 34, 0.7), rgba(3, 14, 22, 0.55));
  border: 1px solid var(--line);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  font-size: 12px;
  color: #e7f1f4;
  white-space: nowrap;
  box-shadow: 0 8px 26px rgba(0, 0, 0, 0.24);
  max-width: min(92vw, 560px);
  overflow: hidden;
}
.quest-kicker { font-size: 8.5px; letter-spacing: 0.28em; color: var(--gold); border-left: 1px solid var(--line-gold); padding-left: 10px; order: 3; }
.quest-dist { color: var(--gold-bright); font-variant-numeric: tabular-nums; font-size: 11px; border-right: 1px solid var(--line); padding-right: 10px; order: 2; }
#questText { text-overflow: ellipsis; overflow: hidden; }

/* ---- toasts ---- */
.toasts {
  position: absolute; top: 136px; left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; gap: 9px; align-items: center;
  width: min(92vw, 440px);
  pointer-events: none;
  z-index: 6;
}
.toast {
  display: flex; align-items: center; gap: 11px;
  padding: 10px 17px 10px 12px;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(10, 37, 51, 0.9), rgba(4, 17, 26, 0.86));
  border: 1px solid var(--line-gold);
  box-shadow: 0 14px 38px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  color: #f2fafb;
  font-size: 13px;
  animation: toastIn 0.55s var(--ease) both;
  max-width: 100%;
}
.toast.out { animation: toastOut 0.5s var(--ease) both; }
.toast b { color: var(--gold-bright); font-weight: 600; }
.toast small { display: block; color: var(--muted); font-size: 10.5px; margin-top: 2px; }
.toast-ico { width: 33px; height: 33px; flex: none; display: grid; place-items: center; border-radius: 50%; background: rgba(233, 200, 138, 0.12); color: var(--gold-bright); border: 1px solid var(--line-gold); }
.toast-ico svg { width: 17px; height: 17px; }
.toast-body { line-height: 1.4; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-12px) scale(0.96); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px) scale(0.97); } }

/* ---- bottom bar ---- */
.hud-bottom {
  position: absolute;
  left: max(22px, env(safe-area-inset-left));
  right: max(22px, env(safe-area-inset-right));
  bottom: max(20px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 18px;
  z-index: 4;
}
.speed-block {
  justify-self: end;
  width: 214px;
  padding: 12px 15px 13px;
  order: 1;
}
.speed-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.label { font-size: 8.5px; letter-spacing: 0.26em; color: var(--muted); text-transform: uppercase; }
.speed-value { display: flex; align-items: baseline; gap: 5px; direction: ltr; }
.speed-value b { font-family: var(--serif); font-size: 34px; line-height: 0.9; font-weight: 400; color: #fbfdfd; font-variant-numeric: tabular-nums; letter-spacing: 0.01em; }
.speed-value i { font-style: normal; font-size: 9.5px; color: var(--muted); letter-spacing: 0.06em; }
.sail-row { display: flex; align-items: center; gap: 8px; margin-top: 11px; }
.sail-label { font-size: 9px; color: var(--muted); letter-spacing: 0.08em; white-space: nowrap; }
.sail-track { flex: 1; height: 4px; border-radius: 3px; background: rgba(255, 255, 255, 0.1); overflow: hidden; }
.sail-fill { height: 100%; width: 0%; border-radius: 3px; background: linear-gradient(90deg, #a6d8cc, var(--gold-bright)); box-shadow: 0 0 10px rgba(233, 200, 138, 0.45); transition: width 0.25s linear; }
.sail-pct { font-size: 9.5px; color: var(--gold-bright); width: 27px; text-align: left; direction: ltr; font-variant-numeric: tabular-nums; }

.hint-bar {
  order: 2;
  justify-self: center;
  display: flex; align-items: center; gap: 6px;
  font-size: 10.5px; color: rgba(230, 242, 246, 0.62);
  padding: 8px 14px;
  border-radius: 10px;
  background: rgba(3, 14, 22, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  white-space: nowrap;
  transition: opacity 1s;
}
.hint-bar.hide { opacity: 0; }
.hint-bar .key { font-family: var(--sans); }
.hint-bar .sep { width: 1px; height: 11px; background: var(--line); margin: 0 4px; }
.key {
  display: inline-grid; place-items: center;
  min-width: 18px; height: 18px; padding: 0 4px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.3);
  font-size: 9.5px; color: #eaf4f7;
  line-height: 1;
}
.key.wide { padding: 0 7px; }

.wind-block {
  order: 3;
  justify-self: start;
  width: 168px;
  padding: 10px 12px;
  display: flex; align-items: center; gap: 8px;
}
#windRose { width: 62px; height: 62px; flex: none; }
.wind-meta { display: flex; flex-direction: column; gap: 1px; direction: ltr; }
.wind-meta .label { direction: rtl; }
.wind-meta b { font-family: var(--serif); font-weight: 400; font-size: 22px; line-height: 1; color: #f7fbfc; font-variant-numeric: tabular-nums; }
.wind-meta i { font-style: normal; font-size: 8.5px; color: var(--muted); letter-spacing: 0.05em; }

/* ---- prompt ---- */
.prompt {
  position: absolute; bottom: 132px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px;
  padding: 11px 18px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(11, 38, 52, 0.92), rgba(4, 17, 26, 0.88));
  border: 1px solid var(--line-gold);
  box-shadow: 0 10px 36px rgba(0, 0, 0, 0.4), 0 0 30px rgba(233, 200, 138, 0.08);
  font-size: 13px; color: #f8fcfd;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  transition: opacity 0.3s, transform 0.3s var(--ease);
  z-index: 5;
  white-space: nowrap;
}
.prompt.is-hidden { opacity: 0; transform: translate(-50%, 10px); pointer-events: none; }
.prompt .key { background: rgba(233, 200, 138, 0.18); border-color: var(--line-gold); color: var(--gold-bright); }

/* ---- touch ---- */
.touch-ui { display: none; }
.touch-ui .joystick {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: max(96px, calc(env(safe-area-inset-bottom) + 84px));
  width: 118px; height: 118px;
  border-radius: 50%;
  border: 1px solid rgba(233, 200, 138, 0.28);
  background: radial-gradient(circle, rgba(8, 31, 44, 0.5), rgba(3, 14, 22, 0.34));
  box-shadow: inset 0 0 30px rgba(0, 0, 0, 0.34), 0 8px 30px rgba(0, 0, 0, 0.25);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  pointer-events: auto;
  touch-action: none;
}
.joystick-ring { position: absolute; inset: 16px; border-radius: 50%; border: 1px dashed rgba(233, 200, 138, 0.16); }
.joystick-knob {
  position: absolute; left: 50%; top: 50%;
  width: 50px; height: 50px; margin: -25px 0 0 -25px;
  border-radius: 50%;
  display: grid; place-items: center;
  color: var(--gold-bright);
  border: 1px solid rgba(233, 200, 138, 0.5);
  background: radial-gradient(circle at 35% 28%, rgba(255, 228, 172, 0.22), rgba(5, 22, 33, 0.86));
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.36), inset 0 0 12px rgba(233, 200, 138, 0.1);
  transition: transform 0.06s linear;
}
.joystick-knob svg { width: 24px; height: 24px; opacity: 0.75; }
.touch-actions {
  position: absolute;
  right: max(20px, env(safe-area-inset-right));
