function makeGlowTexture() {
  const size = 256
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = size
  const ctx = canvas.getContext('2d')
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  g.addColorStop(0, 'rgba(255,244,214,1)')
  g.addColorStop(0.18, 'rgba(255,224,158,0.65)')
  g.addColorStop(0.45, 'rgba(255,190,110,0.18)')
  g.addColorStop(1, 'rgba(255,180,90,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

const skyVert = /* glsl */ `
  varying vec3 vDir;
  void main() {
    vDir = position;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
  }
`

const skyFrag = /* glsl */ `
  uniform vec3 uTopColor;
  uniform vec3 uHorizonColor;
  uniform vec3 uGroundColor;
  uniform vec3 uSunColor;
  uniform vec3 uSunDir;
  uniform vec3 uMoonDir;
  uniform vec3 uCloudLit;
  uniform vec3 uCloudShade;
  uniform float uTime;
  uniform float uNight;
  uniform float uStorm;
  uniform float uFlash;
  uniform float uCloudAmount;
  varying vec3 vDir;

  float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
  }
  float hash31(vec3 p) {
    p = fract(p * 0.3183099 + 0.1);
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
  }
  float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
  }
  float fbm5(vec2 p) {
    float s = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
      s += a * vnoise(p);
      p = p * 2.03 + vec2(11.7, -7.3);
      a *= 0.5;
    }
    return s;
  }

  void main() {
    vec3 dir = normalize(vDir);
    float h = clamp(dir.y, -1.0, 1.0);

    vec3 col = mix(uHorizonColor, uTopColor, pow(clamp(h, 0.0, 1.0), 0.52));
    col = mix(col, uGroundColor, smoothstep(0.0, -0.16, h));

    // sun halo + disc
    float sd = max(dot(dir, uSunDir), 0.0);
    float halo = pow(sd, 5.0) * 0.32 + pow(sd, 42.0) * 0.55 + pow(sd, 260.0) * 1.3;
    col += uSunColor * halo * mix(0.7, 0.32, uStorm);
    float disc = smoothstep(0.99935, 0.99972, sd);
    col += uSunColor * disc * 3.0 * (1.0 - uStorm * 0.7);

    // moon
    float md = max(dot(dir, uMoonDir), 0.0);
    float moonDisc = smoothstep(0.99955, 0.99978, md);
    float moonGlow = pow(md, 160.0) * 0.35;
    float craters = 0.82 + 0.18 * vnoise(dir.xz * 900.0);
    col += vec3(0.78, 0.86, 1.0) * (moonDisc * craters * 1.35 + moonGlow) * uNight;

    // stars
    if (uNight > 0.01 && h > 0.0) {
      vec3 cell = floor(dir * 460.0);
      float star = step(0.9968, hash31(cell));
      float twinkle = 0.55 + 0.45 * sin(uTime * 2.4 + hash31(cell + 7.0) * 40.0);
      float band = fbm5(dir.xz * 5.0 + 3.0) * 0.06;
      col += vec3(0.82, 0.9, 1.0) * (star * twinkle * 0.9 + band) * uNight * smoothstep(0.0, 0.22, h);
    }

    // clouds
    float cloudMask = smoothstep(0.015, 0.16, h) * (1.0 - smoothstep(0.88, 1.0, h) * 0.35);
    vec2 cuv = dir.xz / (h + 0.16);
    cuv = cuv * 0.42 + vec2(uTime * 0.0035, uTime * 0.0016);
    float c1 = fbm5(cuv * 1.25);
    float c2 = fbm5(cuv * 3.4 + 8.0 - vec2(uTime * 0.01, 0.0));
    float c = c1 * 0.78 + c2 * 0.32;
    float cover = smoothstep(0.46 - uCloudAmount * 0.14, 0.78, c) * cloudMask;
    float lit = clamp(dot(dir, uSunDir) * 0.5 + 0.55, 0.0, 1.0);
    vec3 cloudCol = mix(uCloudShade, uCloudLit, pow(lit, 1.7));
    cloudCol = mix(cloudCol, uHorizonColor, (1.0 - smoothstep(0.02, 0.42, h)) * 0.32);
    cloudCol *= mix(1.0, 0.55, uStorm);
    col = mix(col, cloudCol, cover * 0.82);

    // storm
    col = mix(col, vec3(0.25, 0.29, 0.34), uStorm * 0.52);
    col *= mix(1.0, 0.62, uStorm);
    col += vec3(0.72, 0.8, 1.0) * uFlash * (0.55 + cover * 0.9);

    gl_FragColor = vec4(col, 1.0);
    #include <tonemapping_fragment>
    #include <colorspace_fragment>
  }
`

export class Sky {
  constructor(scene) {
    this.scene = scene
    this.group = new THREE.Group()
    this.group.renderOrder = -10
    scene.add(this.group)

    this.uniforms = {
      uTopColor: { value: new THREE.Color('#2b6cb0') },
      uHorizonColor: { value: new THREE.Color('#b9dcf2') },
      uGroundColor: { value: new THREE.Color('#0b2230') },
      uSunColor: { value: new THREE.Color('#fff1d6') },
      uSunDir: { value: new THREE.Vector3(0.4, 0.4, -0.8) },
      uMoonDir: { value: new THREE.Vector3(-0.4, -0.4, 0.8) },
      uCloudLit: { value: new THREE.Color('#fdf7ee') },
      uCloudShade: { value: new THREE.Color('#8fa6b8') },
      uTime: { value: 0 },
      uNight: { value: 0 },
      uStorm: { value: 0 },
      uFlash: { value: 0 },
      uCloudAmount: { value: 0.55 }
    }

    const geo = new THREE.SphereGeometry(4600, 40, 24)
    const mat = new THREE.ShaderMaterial({
      uniforms: this.uniforms,
      vertexShader: skyVert,
      fragmentShader: skyFrag,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false
    })
    this.dome = new THREE.Mesh(geo, mat)
    this.dome.frustumCulled = false
    this.dome.renderOrder = -100
    this.group.add(this.dome)

    // warm glow sprite near the sun for a soft, filmic flare
    const glowMat = new THREE.SpriteMaterial({
      map: makeGlowTexture(),
      color: 0xffffff,
      transparent: true,
      opacity: 0.5,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      depthTest: false,
      fog: false
    })
    this.glow = new THREE.Sprite(glowMat)
    this.glow.scale.set(1400, 1400, 1)
    this.glow.renderOrder = -90
    this.glow.frustumCulled = false
    this.group.add(this.glow)
  }

  update(camera, palette, { time, sunDir, moonDir, storm, flash }) {
    this.group.position.copy(camera.position)
    this.uniforms.uTime.value = time
    this.uniforms.uSunDir.value.copy(sunDir)
    this.uniforms.uMoonDir.value.copy(moonDir)
    this.uniforms.uTopColor.value.copy(palette.top)
    this.uniforms.uHorizonColor.value.copy(palette.horizon)
    this.uniforms.uGroundColor.value.copy(palette.fog).multiplyScalar(0.35)
    this.uniforms.uSunColor.value.copy(palette.sun)
    this.uniforms.uCloudLit.value.copy(palette.cloudLit)
    this.uniforms.uCloudShade.value.copy(palette.cloudShade)
    this.uniforms.uNight.value = palette.night
    this.uniforms.uStorm.value = storm
    this.uniforms.uFlash.value = flash
    this.uniforms.uCloudAmount.value = palette.cloudAmount

    this.glow.position.copy(sunDir).multiplyScalar(3800)
    this.glow.material.opacity = (0.42 * (1 - storm * 0.6)) * smoothstep(-0.1, 0.08, sunDir.y)
    this.glow.material.color.copy(palette.sun)
    this.dome.visible = true
  }
}

const palette = {
  top: new THREE.Color(),
  horizon: new THREE.Color(),
  fog: new THREE.Color(),
  sun: new THREE.Color(),
  cloudLit: new THREE.Color(),
  cloudShade: new THREE.Color(),
  night: 0,
  sunIntensity: 0,
  ambientIntensity: 0,
  ambientSky: new THREE.Color(),
  ambientGround: new THREE.Color(),
  cloudAmount: 0.55,
  exposure: 1
}

export function computePalette(sunDir, storm) {
  const e = sunDir.y
  const dayT = smoothstep(0.08, 0.62, e)
  const nightT = smoothstep(0.02, -0.24, e)

  if (e >= 0) {
    palette.top.copy(SWATCH.goldenTop).lerp(SWATCH.dayTop, dayT)
    palette.horizon.copy(SWATCH.goldenHorizon).lerp(SWATCH.dayHorizon, dayT)
    palette.fog.copy(SWATCH.goldenFog).lerp(SWATCH.dayFog, dayT)
    palette.sun.copy(SWATCH.goldenSun).lerp(SWATCH.daySun, dayT)
    palette.cloudLit.copy(SWATCH.cloudLitGold).lerp(SWATCH.cloudLitDay, dayT)
    palette.cloudShade.copy(SWATCH.cloudShadeGold).lerp(SWATCH.cloudShadeDay, dayT)
  } else {
    palette.top.copy(SWATCH.duskTop).lerp(SWATCH.nightTop, nightT)
    palette.horizon.copy(SWATCH.duskHorizon).lerp(SWATCH.nightHorizon, nightT)
    palette.fog.copy(SWATCH.duskFog).lerp(SWATCH.nightFog, nightT)
    palette.sun.copy(SWATCH.duskSun).lerp(SWATCH.nightSun, nightT)
    palette.cloudLit.copy(SWATCH.cloudLitGold).lerp(SWATCH.cloudLitNight, nightT)
    palette.cloudShade.copy(SWATCH.cloudShadeGold).lerp(SWATCH.cloudShadeNight, nightT)
  }

  palette.night = nightT
  const daylight = smoothstep(-0.06, 0.35, e)
  palette.sunIntensity = lerp(0.0, 3.1, daylight) * (1 - storm * 0.72)
  palette.ambientIntensity = lerp(0.2, 0.62, daylight) * (1 - storm * 0.35)
  palette.ambientSky.copy(palette.horizon).lerp(palette.top, 0.4)
  palette.ambientGround.copy(palette.fog).multiplyScalar(0.55)
  palette.cloudAmount = clamp(0.55 + storm * 0.3, 0, 1)
  palette.exposure = lerp(1.05, 1.28, nightT) * lerp(1, 0.9, storm)

  if (storm > 0.01) {
    palette.top.lerp(new THREE.Color('#2a3038'), storm * 0.7)
    palette.horizon.lerp(new THREE.Color('#4b525a'), storm * 0.66)
    palette.fog.lerp(new THREE.Color('#3d454e'), storm * 0.62)
    palette.cloudLit.lerp(new THREE.Color('#7b8188'), storm * 0.7)
    palette.cloudShade.lerp(new THREE.Color('#363c44'), storm * 0.7)
  }

  // atmospheric tint toward the sun for low light
  if (e > -0.05 && e < 0.3) {
    palette.horizon.lerp(palette.sun, 0.08 * (1 - Math.abs(e - 0.08) / 0.22))
  }

  return palette
}

export function sunDirection(hour, out = new THREE.Vector3()) {
  const elevation = Math.sin(((hour - 6) / 12) * Math.PI) * (Math.PI * 0.42)
  const azimuth = (hour / 24) * Math.PI * 2 + Math.PI * 0.55
  const ce = Math.cos(elevation)
  out.set(Math.sin(azimuth) * ce, Math.sin(elevation), Math.cos(azimuth) * ce)
  return out.normalize()
}

import * as THREE from 'three'

// Wave train. The same constants are mirrored in JS so the hull floats on the
// exact surface the shader draws.
const WAVES = [
  { dx: 0.94, dz: 0.34, k: (Math.PI * 2) / 118, amp: 0.52, omega: 0.40 },
  { dx: -0.42, dz: 0.91, k: (Math.PI * 2) / 71, amp: 0.34, omega: 0.53 },
  { dx: 0.72, dz: -0.69, k: (Math.PI * 2) / 43, amp: 0.19, omega: 0.71 },
  { dx: -0.97, dz: -0.24, k: (Math.PI * 2) / 26, amp: 0.085, omega: 0.95 }
]

function makeGeometry(rings = 150, segments = 176) {
  const positions = []
  const indices = []
  // center vertex
  positions.push(0, 0, 0)
  const radii = []
  const maxR = 4600
  const minR = 1.4
  for (let i = 0; i <= rings; i++) {
    const t = i / rings
    radii.push(minR * Math.pow(maxR / minR, t))
  }
  for (let i = 0; i < rings; i++) {
    const r = radii[i]
    for (let j = 0; j < segments; j++) {
      const a = (j / segments) * Math.PI * 2
      positions.push(Math.cos(a) * r, 0, Math.sin(a) * r)
    }
  }
  // inner fan
  for (let j = 0; j < segments; j++) {
    const a = 1 + j
    const b = 1 + ((j + 1) % segments)
    indices.push(0, b, a)
  }
  // rings
  for (let i = 0; i < rings - 1; i++) {
    const row = 1 + i * segments
    const next = row + segments
    for (let j = 0; j < segments; j++) {
      const a = row + j
      const b = row + ((j + 1) % segments)
      const c = next + j
      const d = next + ((j + 1) % segments)
      indices.push(a, b, c)
      indices.push(b, d, c)
    }
  }
  const geo = new THREE.BufferGeometry()
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
  geo.setIndex(indices)
  geo.boundingSphere = new THREE.Sphere(new THREE.Vector3(), maxR * 1.2)
  return geo
}

const vert = /* glsl */ `
  uniform float uTime;
  uniform float uStorm;
  varying vec3 vWorldPos;
  varying vec3 vNormal;
  varying float vHeight;
  varying float vCrest;

  float waveHeight(vec2 p, float t) {
    float amp = 1.0 + uStorm * 1.15;
    float h = 0.0;
    h += 0.52 * amp * sin(dot(p, vec2(0.94, 0.34)) * 0.053239 - t * 0.40);
    h += 0.34 * amp * sin(dot(p, vec2(-0.42, 0.91)) * 0.088493 - t * 0.53 + 0.9);
    h += 0.19 * amp * sin(dot(p, vec2(0.72, -0.69)) * 0.146088 - t * 0.71 + 2.2);
    h += 0.085 * amp * sin(dot(p, vec2(-0.97, -0.24)) * 0.241661 - t * 0.95 + 4.1);
    return h;
  }

  void main() {
    vec3 wp = (modelMatrix * vec4(position, 1.0)).xyz;
    float h = waveHeight(wp.xz, uTime);
    float e = 3.2;
    float hx = waveHeight(wp.xz + vec2(e, 0.0), uTime);
    float hz = waveHeight(wp.xz + vec2(0.0, e), uTime);
    wp.y += h;

    vec3 n = normalize(vec3(h - hx, e, h - hz));
    vec4 mv = viewMatrix * vec4(wp, 1.0);
    vWorldPos = wp;
    vNormal = n;
    vHeight = h;
    vCrest = (h - waveHeight(wp.xz + vec2(0.0), uTime)) / max(abs(h), 0.001);
    gl_Position = projectionMatrix * mv;
  }
`

const frag = /* glsl */ `
  uniform float uTime;
  uniform float uFogDensity;
  uniform float uStorm;
  uniform vec3 uCamera;
  uniform vec3 uSunDir;
  uniform vec3 uSunColor;
  uniform vec3 uDeep;
  uniform vec3 uShallow;
  uniform vec3 uHorizon;
  uniform vec3 uTop;
  uniform vec3 uFogColor;
  uniform vec4 uIslands[8];
  uniform int uIslandCount;

  varying vec3 vWorldPos;
  varying vec3 vNormal;
  varying float vHeight;
  varying float vCrest;

  float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
  }
  float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
  }
  float fbm3(vec2 p) {
    float s = 0.0;
    float a = 0.5;
    for (int i = 0; i < 3; i++) {
      s += a * vnoise(p);
      p = p * 2.07 + vec2(5.2, -3.7);
      a *= 0.5;
    }
    return s;
  }

  void main() {
    vec2 p = vWorldPos.xz;
    vec3 view = uCamera - vWorldPos;
    float dist = length(view);
    vec3 V = view / dist;
    vec3 N = normalize(vNormal);

    // fine ripples, faded with distance to avoid shimmering
    float rFade = 1.0 - smoothstep(120.0, 900.0, dist);
    vec2 q1 = p * 0.55 + vec2(uTime * 0.22, -uTime * 0.17);
    float n1 = vnoise(q1);
    float nx1 = vnoise(q1 + vec2(0.34, 0.0));
    float nz1 = vnoise(q1 + vec2(0.0, 0.34));
    vec2 q2 = p * 1.75 - vec2(uTime * 0.36, uTime * 0.28);
    float n2 = vnoise(q2);
    float nx2 = vnoise(q2 + vec2(0.28, 0.0));
    float nz2 = vnoise(q2 + vec2(0.0, 0.28));
    N = normalize(N + vec3(n1 - nx1, 0.0, n1 - nz1) * 0.85 * rFade + vec3(n2 - nx2, 0.0, n2 - nz2) * 0.35 * rFade);

    // shoreline + lagoon tint
    float shallow = 0.0;
    float shore = 0.0;
    for (int i = 0; i < 8; i++) {
      if (i >= uIslandCount) break;
      vec4 isl = uIslands[i];
      float d = length(p - isl.xy) - isl.z;
      shallow = max(shallow, 1.0 - smoothstep(0.0, 110.0, max(d, 0.0)));
      if (d > -14.0) {
        shore = max(shore, 1.0 - smoothstep(-2.0, 26.0, d));
      }
    }

    vec3 water = mix(uDeep, uShallow, shallow * 0.9);
    // subtle depth variation
    water *= 0.94 + 0.06 * fbm3(p * 0.012 + 4.0);

    float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 5.0);
    fres = mix(0.035, 1.0, fres);
    vec3 R = reflect(-V, N);
    vec3 sky = mix(uHorizon, uTop, pow(clamp(R.y, 0.0, 1.0), 0.5));
    float sd = max(dot(R, uSunDir), 0.0);
    float sunUp = smoothstep(-0.05, 0.12, uSunDir.y);
    vec3 spec = uSunColor * (pow(sd, 780.0) * 3.4 + pow(sd, 60.0) * 0.22) * sunUp;
    // glitter
    float sparkle = smoothstep(0.72, 0.98, fbm3(p * 1.6 + uTime * 0.35));
    spec += uSunColor * sparkle * pow(sd, 24.0) * 0.35 * sunUp;

    vec3 col = mix(water, sky, fres * 0.86);
    col += spec;

    // wave crest foam
    float crest = smoothstep(0.55, 1.05, vHeight * (1.0 + uStorm * 1.7));
    float foamNoise = fbm3(p * 0.42 + vec2(uTime * 0.13, -uTime * 0.09));
    float foam = crest * smoothstep(0.35, 0.78, foamNoise) * 0.55;

    // surf washing on the beaches
    float stripes = 0.5 + 0.5 * sin(vWorldPos.z * 0.32 + vWorldPos.x * 0.18 - uTime * 1.6);
    float surf = shore * smoothstep(0.22, 0.85, fbm3(p * 0.3 + uTime * 0.08)) * (0.45 + 0.55 * stripes);
    foam = clamp(foam + shore * 0.45 + surf * 0.55, 0.0, 0.95);

    vec3 foamCol = mix(vec3(0.72, 0.83, 0.86), vec3(1.0), 0.6);
    col = mix(col, foamCol, foam * 0.9);

    // storm dims and desaturates the sea
    col = mix(col, vec3(0.12, 0.19, 0.23), uStorm * 0.45);
    col *= mix(1.0, 0.75, uStorm);

    // atmospheric fog
    float fog = 1.0 - exp(-pow(dist * uFogDensity, 2.0));
    col = mix(col, uFogColor, clamp(fog, 0.0, 1.0));

    gl_FragColor = vec4(col, 1.0);
    #include <tonemapping_fragment>
    #include <colorspace_fragment>
  }
`

export class Ocean {
  constructor(scene, islandSlots = 8) {
    this.scene = scene
    this.time = 0
    this.storm = 0
    this.uniforms = {
      uTime: { value: 0 },
      uStorm: { value: 0 },
      uFogDensity: { value: 0.00062 },
      uCamera: { value: new THREE.Vector3() },
      uSunDir: { value: new THREE.Vector3(0.3, 0.5, -0.8) },
      uSunColor: { value: new THREE.Color('#fff1d6') },
      uDeep: { value: new THREE.Color('#04283a') },
      uShallow: { value: new THREE.Color('#1fb3ad') },
      uHorizon: { value: new THREE.Color('#b9dcf2') },
      uTop: { value: new THREE.Color('#2b6cb0') },
      uFogColor: { value: new THREE.Color('#a8c9dd') },
      uIslands: { value: Array.from({ length: islandSlots }, () => new THREE.Vector4(0, 0, 100, 0)) },
      uIslandCount: { value: 0 }
    }
    const mat = new THREE.ShaderMaterial({
      uniforms: this.uniforms,
      vertexShader: vert,
      fragmentShader: frag,
      fog: false
    })
    this.mesh = new THREE.Mesh(makeGeometry(), mat)
    this.mesh.frustumCulled = false
    this.mesh.matrixAutoUpdate = true
    this.mesh.renderOrder = 1
    scene.add(this.mesh)

    this._offset = new THREE.Vector2()
  }

  setIslands(islands) {
    const list = this.uniforms.uIslands.value
    for (let i = 0; i < list.length; i++) {
      const isl = islands[i]
      if (isl) list[i].set(isl.position.x, isl.position.z, isl.waterRadius, isl.height)
      else list[i].set(0, 0, 0, 0)
    }
    this.uniforms.uIslandCount.value = Math.min(list.length, islands.length)
  }

  update(dt, camera, palette, sunDir, storm) {
    this.time += dt * (1 + storm * 0.35)
    this.storm = storm
    const u = this.uniforms
    u.uTime.value = this.time
    u.uStorm.value = storm
    u.uCamera.value.copy(camera.position)
    u.uSunDir.value.copy(sunDir)
    u.uSunColor.value.copy(palette.sun)
    u.uHorizon.value.copy(palette.horizon)
    u.uTop.value.copy(palette.top)
    u.uFogColor.value.copy(palette.fog)
    u.uDeep.value.setHex(0x04283a).lerp(palette.top, 0.1).multiplyScalar(1 - palette.night * 0.35)
    u.uShallow.value.setHex(0x1fb3ad).lerp(palette.sun, 0.08).multiplyScalar(1 - palette.night * 0.45)
    u.uFogDensity.value = 0.00062 + storm * 0.00125 + palette.night * 0.00012

    this.mesh.position.set(camera.position.x, 0, camera.position.z)
  }

  heightAt(x, z, time = this.time) {
    const amp = 1 + this.storm * 1.15
    let h = 0
    h += 0.52 * amp * Math.sin((x * 0.94 + z * 0.34) * 0.053239 - time * 0.40)
    h += 0.34 * amp * Math.sin((x * -0.42 + z * 0.91) * 0.088493 - time * 0.53 + 0.9)
    h += 0.19 * amp * Math.sin((x * 0.72 + z * -0.69) * 0.146088 - time * 0.71 + 2.2)
    h += 0.085 * amp * Math.sin((x * -0.97 + z * -0.24) * 0.241661 - time * 0.95 + 4.1)
    return h
  }

  normalAt(x, z, out = new THREE.Vector3()) {
    const e = 3.2
    const h = this.heightAt(x, z)
    const hx = this.heightAt(x + e, z)
    const hz = this.heightAt(x, z + e)
    return out.set(h - hx, e, h - hz).normalize()
  }
}

export { WAVES }

import * as THREE from 'three'

const pointVert = /* glsl */ `
  attribute float aLife;
  attribute float aSize;
  attribute float aSeed;
  varying float vLife;
  varying float vSeed;
  uniform float uPixelScale;
  void main() {
    vLife = aLife;
    vSeed = aSeed;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * uPixelScale / max(1.0, -mv.z);
    gl_Position = projectionMatrix * mv;
  }
`

const pointFrag = /* glsl */ `
  varying float vLife;
  varying float vSeed;
  uniform vec3 uColor;
  uniform vec3 uColor2;
  uniform float uOpacity;
  void main() {
    vec2 p = gl_PointCoord - 0.5;
    float d = length(p);
    if (d > 0.5) discard;
    float soft = smoothstep(0.5, 0.08, d);
    float core = smoothstep(0.32, 0.0, d);
    vec3 col = mix(uColor, uColor2, core * 0.55 + vSeed * 0.2);
    float a = soft * vLife * uOpacity;
    if (a < 0.01) discard;
    gl_FragColor = vec4(col, a);
    #include <colorspace_fragment>
  }
`

export class ParticleField {
  constructor(scene, {
    count = 520,
    color = '#eaf6f7',
    color2 = '#ffffff',
    opacity = 0.8,
    blending = THREE.NormalBlending,
    pixelScale = 220
  } = {}) {
    this.count = count
    this.cursor = 0
    this.particles = new Array(count)
    for (let i = 0; i < count; i++) {
      this.particles[i] = {
        active: false,
        x: 0, y: -999, z: 0,
        vx: 0, vy: 0, vz: 0,
        life: 0, maxLife: 1, size: 1, drag: 1, gravity: 0, wave: 0
      }
    }
    this.positions = new Float32Array(count * 3)
    this.life = new Float32Array(count)
    this.sizes = new Float32Array(count)
    this.seeds = new Float32Array(count)
    for (let i = 0; i < count; i++) {
      this.positions[i * 3 + 1] = -999
      this.sizes[i] = 1
      this.seeds[i] = Math.random()
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    geo.setAttribute('aLife', new THREE.BufferAttribute(this.life, 1))
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1))
    geo.setAttribute('aSeed', new THREE.BufferAttribute(this.seeds, 1))
    geo.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 1e6)

    this.uniforms = {
      uColor: { value: new THREE.Color(color) },
      uColor2: { value: new THREE.Color(color2) },
      uOpacity: { value: opacity },
      uPixelScale: { value: pixelScale }
    }
    const mat = new THREE.ShaderMaterial({
      uniforms: this.uniforms,
      vertexShader: pointVert,
      fragmentShader: pointFrag,
      transparent: true,
      depthWrite: false,
      blending,
      fog: false
    })
    this.points = new THREE.Points(geo, mat)
    this.points.frustumCulled = false
    this.points.renderOrder = 5
    scene.add(this.points)
    this.geo = geo
  }

  spawn(x, y, z, vx, vy, vz, maxLife, size, { drag = 0.9, gravity = 0, wave = 0 } = {}) {
    const p = this.particles[this.cursor]
    this.cursor = (this.cursor + 1) % this.count
    p.active = true
    p.x = x; p.y = y; p.z = z
    p.vx = vx; p.vy = vy; p.vz = vz
    p.life = maxLife
    p.maxLife = maxLife
    p.size = size
    p.drag = drag
    p.gravity = gravity
    p.wave = wave
    return p
  }

  update(dt, time, ocean) {
    const pos = this.positions
    const lifeAttr = this.life
    const sizeAttr = this.sizes
    for (let i = 0; i < this.count; i++) {
      const p = this.particles[i]
      if (!p.active) continue
      p.life -= dt
      if (p.life <= 0) {
        p.active = false
        pos[i * 3 + 1] = -999
        lifeAttr[i] = 0
        continue
      }
      const dragK = Math.pow(p.drag, dt * 60)
      p.vx *= dragK
      p.vz *= dragK
      p.vy = p.vy * dragK - p.gravity * dt
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.z += p.vz * dt
      if (ocean && p.y < ocean.heightAt(p.x, p.z, time) + 0.05) {
        p.y = ocean.heightAt(p.x, p.z, time) + 0.05
        p.vy *= 0.3
      }
      const l = p.life / p.maxLife
      lifeAttr[i] = l
      sizeAttr[i] = p.size * (0.35 + 0.65 * Math.sqrt(l))
      pos[i * 3] = p.x
      pos[i * 3 + 1] = p.y
      pos[i * 3 + 2] = p.z
    }
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.aLife.needsUpdate = true
    this.geo.attributes.aSize.needsUpdate = true
  }
}

export function makeRadialTexture(size = 128, inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)') {
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = size
  const ctx = canvas.getContext('2d')
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  g.addColorStop(0, inner)
  g.addColorStop(1, outer)
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

import * as THREE from 'three'
import { clamp, damp, lerp, smoothstep } from './noise.js'

export const SHIP = { length: 16, beam: 5.4, draft: 0.55, mastHeight: 17 }

function makeWoodTexture(seed = 1, base = '#7c4a2a', dark = '#4a2a17') {
  const w = 512
  const h = 512
  const canvas = document.createElement('canvas')
  canvas.width = w
  canvas.height = h
  const ctx = canvas.getContext('2d')
  ctx.fillStyle = base
  ctx.fillRect(0, 0, w, h)
  let s = seed * 9301
  const rnd = () => {
    s = (s * 9301 + 49297) % 233280
    return s / 233280
  }
  // planks along the hull
  const rows = 8
  const rh = h / rows
  for (let r = 0; r < rows; r++) {
    const shade = 0.82 + rnd() * 0.26
    ctx.fillStyle = `rgba(${Math.floor(28 * shade)},${Math.floor(16 * shade)},${Math.floor(9 * shade)},0.35)`
    ctx.fillRect(0, r * rh, w, rh)
    // grain
    for (let g = 0; g < 26; g++) {
      const y = r * rh + rnd() * rh
      ctx.beginPath()
      ctx.strokeStyle = `rgba(30,16,8,${0.06 + rnd() * 0.12})`
      ctx.lineWidth = 0.6 + rnd() * 1.4
      ctx.moveTo(0, y)
      for (let x = 0; x <= w; x += 32) {
        ctx.lineTo(x, y + Math.sin(x * 0.03 + g) * 2.4 + (rnd() - 0.5) * 3)
      }
      ctx.stroke()
    }
    // plank seam
    ctx.fillStyle = 'rgba(25,12,7,0.55)'
    ctx.fillRect(0, r * rh, w, 2)
    ctx.fillStyle = 'rgba(255,214,160,0.08)'
    ctx.fillRect(0, r * rh + 2, w, 1)
  }
  // subtle sheen
  const grad = ctx.createLinearGradient(0, 0, 0, h)
  grad.addColorStop(0, 'rgba(255,220,180,0.10)')
  grad.addColorStop(0.5, 'rgba(255,255,255,0)')
  grad.addColorStop(1, 'rgba(0,0,0,0.18)')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, w, h)
  const tex = new THREE.CanvasTexture(canvas)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  return tex
}

function makeSailTexture() {
  const w = 512
  const h = 512
  const canvas = document.createElement('canvas')
  canvas.width = w
  canvas.height = h
  const ctx = canvas.getContext('2d')
  const grad = ctx.createLinearGradient(0, 0, 0, h)
  grad.addColorStop(0, '#fbf4e4')
  grad.addColorStop(0.55, '#f1e6cf')
  grad.addColorStop(1, '#e3d4b8')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, w, h)
  // seams
  for (let x = 0; x < w; x += 64) {
    ctx.fillStyle = 'rgba(120,100,72,0.22)'
    ctx.fillRect(x, 0, 2, h)
    ctx.fillStyle = 'rgba(255,255,255,0.18)'
    ctx.fillRect(x + 2, 0, 2, h)
  }
  for (let y = 0; y < h; y += 128) {
    ctx.fillStyle = 'rgba(130,110,80,0.12)'
    ctx.fillRect(0, y, w, 2)
  }
  // weather stains and patches
  for (let i = 0; i < 24; i++) {
    const x = Math.random() * w
    const y = Math.random() * h
    const r = 8 + Math.random() * 46
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, `rgba(150,120,80,${0.03 + Math.random() * 0.07})`)
    g.addColorStop(1, 'rgba(150,120,80,0)')
    ctx.fillStyle = g
    ctx.beginPath()
    ctx.arc(x, y, r, 0, Math.PI * 2)
    ctx.fill()
  }
  // emblem
  ctx.save()
  ctx.globalAlpha = 0.1
  ctx.strokeStyle = '#8a5a2a'
  ctx.lineWidth = 4
  ctx.beginPath()
  ctx.arc(w * 0.5, h * 0.42, 58, 0, Math.PI * 2)
  ctx.stroke()
  ctx.beginPath()
  ctx.arc(w * 0.5, h * 0.42, 34, 0, Math.PI * 2)
  ctx.stroke()
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2
    ctx.beginPath()
    ctx.moveTo(w * 0.5 + Math.cos(a) * 40, h * 0.42 + Math.sin(a) * 40)
    ctx.lineTo(w * 0.5 + Math.cos(a) * 56, h * 0.42 + Math.sin(a) * 56)
    ctx.stroke()
  }
  ctx.restore()
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  return tex
}

function makeFlagTexture() {
  const w = 256
  const h = 144
  const canvas = document.createElement('canvas')
  canvas.width = w
  canvas.height = h
  const ctx = canvas.getContext('2d')
  const grad = ctx.createLinearGradient(0, 0, 0, h)
  grad.addColorStop(0, '#124a5c')
  grad.addColorStop(1, '#0a2d3b')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, w, h)
  ctx.strokeStyle = '#e9c88a'
  ctx.lineWidth = 6
  ctx.strokeRect(8, 8, w - 16, h - 16)
  ctx.strokeStyle = '#f3d9a0'
  ctx.lineWidth = 5
  ctx.beginPath()
  ctx.arc(w / 2, h / 2, 30, 0, Math.PI * 2)
  ctx.stroke()
  ctx.beginPath()
  ctx.moveTo(w / 2, h / 2 - 42)
  ctx.lineTo(w / 2, h / 2 + 42)
  ctx.moveTo(w / 2 - 36, h / 2)
  ctx.lineTo(w / 2 + 36, h / 2)
  ctx.stroke()
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2
    ctx.beginPath()
    ctx.moveTo(w / 2 + Math.cos(a) * 34, h / 2 + Math.sin(a) * 34)
    ctx.lineTo(w / 2 + Math.cos(a) * 46, h / 2 + Math.sin(a) * 46)
    ctx.stroke()
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function makeNameTexture() {
  const w = 512
