251: export function computePalette(sunDir, storm) {
252:   const e = sunDir.y
253:   const dayT = smoothstep(0.08, 0.62, e)
254:   const nightT = smoothstep(0.02, -0.24, e)
255: 
256:   if (e >= 0) {
257:     palette.top.copy(SWATCH.goldenTop).lerp(SWATCH.dayTop, dayT)
258:     palette.horizon.copy(SWATCH.goldenHorizon).lerp(SWATCH.dayHorizon, dayT)
259:     palette.fog.copy(SWATCH.goldenFog).lerp(SWATCH.dayFog, dayT)
260:     palette.sun.copy(SWATCH.goldenSun).lerp(SWATCH.daySun, dayT)
261:     palette.cloudLit.copy(SWATCH.cloudLitGold).lerp(SWATCH.cloudLitDay, dayT)
262:     palette.cloudShade.copy(SWATCH.cloudShadeGold).lerp(SWATCH.cloudShadeDay, dayT)
263:   } else {
264:     palette.top.copy(SWATCH.duskTop).lerp(SWATCH.nightTop, nightT)
265:     palette.horizon.copy(SWATCH.duskHorizon).lerp(SWATCH.nightHorizon, nightT)
266:     palette.fog.copy(SWATCH.duskFog).lerp(SWATCH.nightFog, nightT)
267:     palette.sun.copy(SWATCH.duskSun).lerp(SWATCH.nightSun, nightT)
268:     palette.cloudLit.copy(SWATCH.cloudLitGold).lerp(SWATCH.cloudLitNight, nightT)
269:     palette.cloudShade.copy(SWATCH.cloudShadeGold).lerp(SWATCH.cloudShadeNight, nightT)
270:   }
271: 
272:   palette.night = nightT
273:   const daylight = smoothstep(-0.06, 0.35, e)
274:   palette.sunIntensity = lerp(0.0, 3.1, daylight) * (1 - storm * 0.72)
275:   palette.ambientIntensity = lerp(0.2, 0.62, daylight) * (1 - storm * 0.35)
276:   palette.ambientSky.copy(palette.horizon).lerp(palette.top, 0.4)
277:   palette.ambientGround.copy(palette.fog).multiplyScalar(0.55)
278:   palette.cloudAmount = clamp(0.55 + storm * 0.3, 0, 1)
279:   palette.exposure = lerp(1.05, 1.28, nightT) * lerp(1, 0.9, storm)
280: 
281:   if (storm > 0.01) {
282:     palette.top.lerp(new THREE.Color('#2a3038'), storm * 0.7)
283:     palette.horizon.lerp(new THREE.Color('#4b525a'), storm * 0.66)
284:     palette.fog.lerp(new THREE.Color('#3d454e'), storm * 0.62)
285:     palette.cloudLit.lerp(new THREE.Color('#7b8188'), storm * 0.7)
286:     palette.cloudShade.lerp(new THREE.Color('#363c44'), storm * 0.7)
287:   }
288: 
289:   // atmospheric tint toward the sun for low light
290:   if (e > -0.05 && e < 0.3) {
291:     palette.horizon.lerp(palette.sun, 0.08 * (1 - Math.abs(e - 0.08) / 0.22))
292:   }
293: 
294:   return palette
295: }
