297: export function sunDirection(hour, out = new THREE.Vector3()) {
298:   const elevation = Math.sin(((hour - 6) / 12) * Math.PI) * (Math.PI * 0.42)
299:   const azimuth = (hour / 24) * Math.PI * 2 + Math.PI * 0.55
300:   const ce = Math.cos(elevation)
301:   out.set(Math.sin(azimuth) * ce, Math.sin(elevation), Math.cos(azimuth) * ce)
302:   return out.normalize()
303: }

