import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', e => errors.push(e.message))
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 })
await page.waitForFunction(() => document.fonts.status === 'loaded')
await page.click('#startBtn')
await page.waitForTimeout(800)
console.log('started', await page.evaluate(() => window.__voyage.game.state.started))
// teleport to the home chest and interact
const first = await page.evaluate(() => {
  const g = window.__voyage.game
  const isl = g.home
  window.__voyage.teleport(isl.chestWorld.x, isl.chestWorld.z)
  g.interact()
  return { gold: g.state.gold, chests: g.state.chestCount, open: isl.chestOpened }
})
console.log('first chest', first)
// discover all and open every remaining chest
const all = await page.evaluate(async () => {
  const g = window.__voyage.game
  window.__voyage.discoverAll()
  for (const isl of g.islands) {
    if (isl.chestOpened) continue
    window.__voyage.teleport(isl.chestWorld.x, isl.chestWorld.z)
    g.interact()
  }
  await new Promise(r => setTimeout(r, 1600))
  return { gold: g.state.gold, chests: g.state.chestCount, discovered: g.state.discoveredCount, ended: g.state.ended, victoryVisible: !document.getElementById('victory').classList.contains('is-hidden') }
})
console.log('all', all)
await page.screenshot({ path: 'screenshots/victory-desktop.png' })
console.log('errors', errors.slice(0, 5))
await browser.close()
EOF
